#include <cstdint>
#include <cstring>
#include <string>

namespace { thread_local std::string t_lastError; }

extern "C" const char* lib_result_name(int32_t code)
{
    switch (code)
    {
    case 0: return "LIB_OK";
    case 1: return "LIB_INVALID_ARGUMENT";
    case 2: return "LIB_DIVIDE_BY_ZERO";
    default: return "LIB_UNKNOWN_RESULT";
    }
}

int32_t lib_fail(int32_t code, const std::string& message)
{
    t_lastError = message;
    return code;
}

extern "C" int32_t lib_last_error(char* buffer, int32_t capacity)
{
    const int32_t length{ static_cast<int32_t>(t_lastError.size()) };
    if (buffer && capacity >= 1)
    {
        const int32_t copy{ length < capacity - 1 ? length : capacity - 1 };
        std::memcpy(buffer, t_lastError.data(), static_cast<std::size_t>(copy));
        buffer[copy] = '\0';
    }
    return length;
}

extern "C" int32_t lib_divide(int32_t a, int32_t b, int32_t* out)
{
    if (!out) return lib_fail(1, "out must not be null");
    if (b == 0) return lib_fail(2, "cannot divide " + std::to_string(a) + " by zero");
    *out = a / b;
    return 0;
}

