#include <thread>
std::string lastError() { std::string s(static_cast<std::size_t>(lib_last_error(nullptr, 0)), '\0'); lib_last_error(s.data(), static_cast<int32_t>(s.size()) + 1); return s; }
TEST("names") { CHECK_EQ(std::string(lib_result_name(0)), std::string("LIB_OK")); CHECK_EQ(std::string(lib_result_name(2)), std::string("LIB_DIVIDE_BY_ZERO")); CHECK_EQ(std::string(lib_result_name(77)), std::string("LIB_UNKNOWN_RESULT")); CHECK_EQ(std::string(lib_result_name(-1)), std::string("LIB_UNKNOWN_RESULT")); }
TEST("divide") { int32_t r = 0; CHECK_EQ(lib_divide(17, 5, &r), 0); CHECK_EQ(r, 3); }
TEST("divide by zero") { int32_t r = 9; CHECK_EQ(lib_divide(17, 0, &r), 2); CHECK_EQ(r, 9); CHECK_EQ(lastError(), std::string("cannot divide 17 by zero")); }
TEST("null output") { CHECK_EQ(lib_divide(1, 1, nullptr), 1); CHECK_EQ(lastError(), std::string("out must not be null")); }
TEST("success keeps the last error") { lib_divide(4, 0, nullptr); int32_t r = 0; lib_divide(4, 2, &r); CHECK_EQ(lastError(), std::string("out must not be null")); }
TEST("buffer contract") { lib_fail(5, "abcdef"); char b[4]; CHECK_EQ(lib_last_error(b, 4), 6); CHECK_EQ(std::string(b), std::string("abc")); }
TEST("each thread has its own message") {
    lib_fail(1, "main thread");
    std::string seen;
    std::thread other([&] { seen = lastError(); lib_fail(1, "other thread"); });
    other.join();
    CHECK_EQ(seen, std::string(""));
    CHECK_EQ(lastError(), std::string("main thread"));
}

